import { DomainEvent } from './domain-event';
/**
 * Event raised when a new identity is created.
 */
export class IdentityCreated extends DomainEvent {
  identityId;
  publicKey;
  nickname;
  eventType = 'identity.created';
  constructor(identityId, publicKey, nickname) {
    super();
    this.identityId = identityId;
    this.publicKey = publicKey;
    this.nickname = nickname;
  }
}
/**
 * Event raised when an identity is renamed.
 */
export class IdentityRenamed extends DomainEvent {
  identityId;
  oldNickname;
  newNickname;
  eventType = 'identity.renamed';
  constructor(identityId, oldNickname, newNickname) {
    super();
    this.identityId = identityId;
    this.oldNickname = oldNickname;
    this.newNickname = newNickname;
  }
}
/**
 * Event raised when an identity is selected (made active).
 */
export class IdentitySelected extends DomainEvent {
  identityId;
  previousIdentityId;
  eventType = 'identity.selected';
  constructor(identityId, previousIdentityId) {
    super();
    this.identityId = identityId;
    this.previousIdentityId = previousIdentityId;
  }
}
/**
 * Event raised when an identity signs an event.
 */
export class IdentitySigned extends DomainEvent {
  identityId;
  eventKind;
  signedEventId;
  eventType = 'identity.signed';
  constructor(identityId, eventKind, signedEventId) {
    super();
    this.identityId = identityId;
    this.eventKind = eventKind;
    this.signedEventId = signedEventId;
  }
}
/**
 * Event raised when an identity is deleted.
 */
export class IdentityDeleted extends DomainEvent {
  identityId;
  publicKey;
  eventType = 'identity.deleted';
  constructor(identityId, publicKey) {
    super();
    this.identityId = identityId;
    this.publicKey = publicKey;
  }
}
